macro_rules! deps {
    () => {
        IUnknownImpl!();
        ComObject!();
    };
}

macro_rules! ComObjectInner {
    () => {
        deps!();
        # [doc = " Identifies types that can be placed in [`ComObject`]."] # [doc = ""] # [doc = " This trait links types that can be placed in `ComObject` with the types generated by the"] # [doc = " `#[implement]` macro. The `#[implement]` macro generates implementations of this trait."] # [doc = " The generated types contain the vtable layouts and refcount-related fields for the COM"] # [doc = " object implementation."] # [doc = ""] # [doc = " This trait is an implementation detail of the Windows crates."] # [doc = " User code should not deal directly with this trait."] # [doc = ""] # [doc = " This trait is sort of the reverse of [`IUnknownImpl`]. This trait allows user code to use"] # [doc = " [`ComObject<T>`] instead of `ComObject<T_Impl>`."] pub trait ComObjectInner : Sized { # [doc = " The generated `<foo>_Impl` type (aka the \"boxed\" type or \"outer\" type)."] type Outer : IUnknownImpl < Impl = Self > ; # [doc = " Moves an instance of this type into a new ComObject box and returns it."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " It is important that safe Rust code never be able to acquire an owned instance of a"] # [doc = " generated \"outer\" COM object type, e.g. `<foo>_Impl`. This would be unsafe because the"] # [doc = " `<foo>_Impl` object contains a reference count field and provides methods that adjust"] # [doc = " the reference count, and destroy the object when the reference count reaches zero."] # [doc = ""] # [doc = " Safe Rust code must only be able to interact with these values by accessing them via a"] # [doc = " `ComObject` reference. `ComObject` handles adjusting reference counts and associates the"] # [doc = " lifetime of a `&<foo>_Impl` with the lifetime of the related `ComObject`."] # [doc = ""] # [doc = " The `#[implement]` macro generates the implementation of this `into_object` method."] # [doc = " The generated `into_object` method encapsulates the construction of the `<foo>_Impl`"] # [doc = " object and immediately places it into the heap and returns a `ComObject` reference to it."] # [doc = " This ensures that our requirement -- that safe Rust code never own a `<foo>_Impl` value"] # [doc = " directly -- is met."] fn into_object (self) -> ComObject < Self > ; }
    };
}

ComObjectInner!();